// Builds the Decap CMS content into the static site.
//
//   node scripts/build-articles.mjs
//
// Articles (content/articles/*.md):
//   - each non-draft article becomes posts/<category>/<url_slug>.html, in the same
//     layout as the hand-written articles;
//   - posts/Articles.html gets the article in its author's list: דוד and רפי go to
//     their own sections, "anonymous" goes to "מאמרים נוספים".
// Videos (content/videos/*.md):
//   - each non-draft video becomes a card at the end of its column on index.html.
// Pages generated by an earlier article run whose source was deleted are removed;
// the list of generated files is kept in scripts/generated.json.

import { readdir, readFile, writeFile, rm, access } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import matter from "gray-matter";
import { marked } from "marked";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SRC_DIR = path.join(ROOT, "content", "articles");
const VIDEO_DIR = path.join(ROOT, "content", "videos");
const POSTS_DIR = path.join(ROOT, "posts");
const MANIFEST = path.join(ROOT, "scripts", "generated.json");
const LIST_FILE = path.join(POSTS_DIR, "Articles.html");
const INDEX_FILE = path.join(ROOT, "index.html");
const SLUG_RE = /^[a-z0-9-]+$/;

// Author value (as set in admin/config.yml) -> marker name of the list it goes to in posts/Articles.html.
const AUTHOR_LISTS = {
  david: "articles:david",
  rafi: "articles:rafi",
  anonymous: "articles:anonymous",
};

// Video category (as set in admin/config.yml) -> the id of the column on index.html.
const COLUMNS = ["col-1", "col-2", "col-3", "col-4", "col-5"];

const exists = (p) => access(p).then(() => true, () => false);
const esc = (s) =>
  String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

function formatDate(value) {
  if (!value) return "";
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("he-IL", {
    year: "numeric",
    month: "long",
    day: "numeric",
    timeZone: "Asia/Jerusalem",
  });
}

const SITE = "https://milhemet-tora.com";
const OG_IMAGE = `${SITE}/assets/og-image.png`;

// Link preview tags (Open Graph and Twitter), so a shared article shows its title and summary.
function ogBlock({ title, description, relOut }) {
  const url = `${SITE}/${relOut.split("/").map(encodeURIComponent).join("/")}`;
  return `<!-- og:start -->
<meta property="og:type" content="article"/>
<meta property="og:site_name" content="מלחמת תורה"/>
<meta property="og:locale" content="he_IL"/>
<meta property="og:title" content="${esc(title)}"/>
<meta property="og:description" content="${esc(description)}"/>
<meta property="og:url" content="${esc(url)}"/>
<meta property="og:image" content="${OG_IMAGE}"/>
<meta property="og:image:width" content="1200"/>
<meta property="og:image:height" content="630"/>
<meta property="og:image:alt" content="משקל עם הרמב&quot;ם בצד ימין ודמות מכשפה בצד שמאל"/>
<meta name="twitter:card" content="summary_large_image"/>
<meta name="twitter:title" content="${esc(title)}"/>
<meta name="twitter:description" content="${esc(description)}"/>
<meta name="twitter:image" content="${OG_IMAGE}"/>
<!-- og:end -->
`;
}

function articlePage({ title, description, date, body, depth, relOut }) {
  // Pages sit in posts/<category>/, so the shared assets are two levels up.
  const up = "../".repeat(depth);
  const summary = description || title;
  return `<!DOCTYPE html>
<html dir="rtl" lang="he">
<head>
<meta charset="utf-8"/>
<meta content="width=device-width, initial-scale=1" name="viewport"/>
<title>${esc(title)} · מלחמת תורה</title>
<meta content="${esc(summary)}" name="description"/>
${ogBlock({ title, description: summary, relOut })}<link href="https://fonts.googleapis.com" rel="preconnect"/>
<link crossorigin="" href="https://fonts.gstatic.com" rel="preconnect"/>
<link href="https://fonts.googleapis.com/css2?family=Heebo:wght@400;500;700;800&amp;display=swap" rel="stylesheet"/>
<link href="${up}assets/article.css" rel="stylesheet"/>
<link href="${up}favicon.svg" rel="icon" type="image/svg+xml"/>
<link href="${up}favicon.ico" rel="alternate icon" sizes="any"/>
<link href="${up}apple-touch-icon.png" rel="apple-touch-icon"/>
</head>
<body>
<main class="wrap article">
<nav class="back-top" aria-label="ניווט"><a class="back-link" href="../Articles.html">חזרה למאמרים</a></nav>
<article>
<h1>${esc(title)}</h1>
${date ? `<p class="article-meta">${esc(date)}</p>\n` : ""}<div class="post-body">
${body}
</div>
</article>
</main>
<footer class="wrap foot"><a class="back-link" href="../Articles.html">חזרה למאמרים</a></footer>
</body>
</html>
`;
}

// Replaces what sits between two marker comments, keeping the markers themselves.
function replaceBetween(html, start, end, content, file) {
  const s = html.indexOf(start);
  const e = html.indexOf(end);
  if (s === -1 || e === -1 || e < s) {
    throw new Error(`${file} is missing the "${start}" / "${end}" markers`);
  }
  return html.slice(0, s + start.length) + "\n" + content + html.slice(e);
}

// Accepts a YouTube video link (watch, youtu.be, embed, shorts, live), a bare video id,
// and an optional playlist (&list=...). Returns null when it is not a YouTube link.
function parseYouTube(raw) {
  const s = String(raw).trim();
  if (/^[\w-]{11}$/.test(s)) return { id: s, list: null };

  let u;
  try {
    u = new URL(/^https?:\/\//.test(s) ? s : `https://${s}`);
  } catch {
    return null;
  }
  const host = u.hostname.replace(/^www\./, "").replace(/^m\./, "");
  let id = null;
  if (host === "youtu.be") {
    id = u.pathname.split("/")[1];
  } else if (host === "youtube.com" || host.endsWith(".youtube.com") || host === "youtube-nocookie.com") {
    id = u.searchParams.get("v");
    if (!id) {
      const m = u.pathname.match(/^\/(?:embed|shorts|live)\/([\w-]{11})/);
      if (m) id = m[1];
    }
  } else {
    return null;
  }
  if (!id || !/^[\w-]{11}$/.test(id)) return null;

  const list = u.searchParams.get("list");
  return { id, list: list && /^[\w-]+$/.test(list) ? list : null };
}

async function loadArticles() {
  const files = (await readdir(SRC_DIR)).filter((f) => f.endsWith(".md")).sort();
  const articles = [];
  const seenOutputs = new Set();

  for (const file of files) {
    const raw = await readFile(path.join(SRC_DIR, file), "utf8");
    const { data, content } = matter(raw);
    if (data.draft === true) continue;

    for (const key of ["title", "url_slug", "category", "author"]) {
      if (!data[key]) throw new Error(`${file}: missing field "${key}"`);
    }
    if (!SLUG_RE.test(data.url_slug)) {
      throw new Error(`${file}: url_slug "${data.url_slug}" may only contain a-z, 0-9 and "-"`);
    }
    if (!Object.hasOwn(AUTHOR_LISTS, data.author)) {
      throw new Error(`${file}: unknown author "${data.author}"`);
    }
    if (!(await exists(path.join(POSTS_DIR, data.category)))) {
      throw new Error(`${file}: unknown category folder "posts/${data.category}"`);
    }

    const relOut = path.join("posts", data.category, `${data.url_slug}.html`);
    if (seenOutputs.has(relOut)) throw new Error(`${file}: duplicate output ${relOut}`);
    seenOutputs.add(relOut);

    const body = (await marked.parse(content))
      // Decap stores uploads as site-absolute paths; make them relative to the page.
      .replace(/(src|href)="\/assets\//g, `$1="../../assets/`);

    articles.push({
      title: String(data.title),
      description: String(data.description ?? ""),
      category: String(data.category),
      author: data.author,
      slug: data.url_slug,
      date: data.date ? new Date(data.date) : null,
      body,
      relOut,
    });
  }

  articles.sort((a, b) => (b.date?.getTime() ?? 0) - (a.date?.getTime() ?? 0));
  return articles;
}

async function loadVideos() {
  const files = (await readdir(VIDEO_DIR)).filter((f) => f.endsWith(".md")).sort();
  const videos = [];

  for (const file of files) {
    const raw = await readFile(path.join(VIDEO_DIR, file), "utf8");
    const { data } = matter(raw);
    if (data.draft === true) continue;

    for (const key of ["title", "url", "category"]) {
      if (!data[key]) throw new Error(`${file}: missing field "${key}"`);
    }
    if (!COLUMNS.includes(data.category)) {
      throw new Error(`${file}: unknown category "${data.category}"`);
    }
    const yt = parseYouTube(data.url);
    if (!yt) throw new Error(`${file}: "${data.url}" is not a YouTube link`);

    videos.push({
      title: String(data.title),
      category: data.category,
      id: yt.id,
      list: yt.list,
      date: data.date ? new Date(data.date) : null,
    });
  }

  // Oldest first: new videos go after the ones already in their column.
  videos.sort((a, b) => (a.date?.getTime() ?? 0) - (b.date?.getTime() ?? 0));
  return videos;
}

async function writeArticles(articles) {
  let previous = [];
  if (await exists(MANIFEST)) {
    previous = JSON.parse(await readFile(MANIFEST, "utf8"));
  }
  const current = new Set(articles.map((a) => a.relOut));

  // Refuse to overwrite a hand-written page that this build did not create.
  for (const a of articles) {
    const abs = path.join(ROOT, a.relOut);
    if ((await exists(abs)) && !previous.includes(a.relOut)) {
      throw new Error(`${a.relOut} already exists and was not generated; choose another url_slug`);
    }
  }

  for (const a of articles) {
    const html = articlePage({
      title: a.title,
      description: a.description,
      date: formatDate(a.date),
      body: a.body,
      depth: 2,
      relOut: a.relOut,
    });
    await writeFile(path.join(ROOT, a.relOut), html, "utf8");
  }

  for (const old of previous) {
    if (!current.has(old)) await rm(path.join(ROOT, old), { force: true });
  }

  await writeFile(MANIFEST, JSON.stringify([...current].sort(), null, 2) + "\n", "utf8");
}

async function updateArticleLists(articles) {
  let html = await readFile(LIST_FILE, "utf8");

  for (const [author, marker] of Object.entries(AUTHOR_LISTS)) {
    const items = articles
      .filter((a) => a.author === author)
      .map((a) => {
        const desc = a.description ? `<span class="desc">${esc(a.description)}</span>` : "";
        return `<li><a href="${esc(a.category)}/${esc(a.slug)}.html">${esc(a.title)}</a>${desc}</li>`;
      });
    html = replaceBetween(
      html,
      `<!-- ${marker}:start -->`,
      `<!-- ${marker}:end -->`,
      items.length ? items.join("\n") + "\n" : "",
      LIST_FILE
    );
  }

  await writeFile(LIST_FILE, html, "utf8");
}

async function updateIndex(videos) {
  let html = await readFile(INDEX_FILE, "utf8");

  for (const col of COLUMNS) {
    const start = `<!-- videos:${col}:start -->`;
    const end = `<!-- videos:${col}:end -->`;

    const sectionAt = html.indexOf(`<section class="col" id="${col}"`);
    if (sectionAt === -1) throw new Error(`index.html has no column "${col}"`);
    const heading = html.slice(sectionAt).match(/<h2 class="colhead-m">([^<]*)<\/h2>/);
    if (!heading) throw new Error(`index.html column "${col}" has no heading`);

    // The hand-written cards come before the start marker; number new cards after them.
    const startAt = html.indexOf(start, sectionAt);
    if (startAt === -1) throw new Error(`index.html is missing the "${start}" marker`);
    const existing = (html.slice(sectionAt, startAt).match(/<div class="slot">/g) || []).length;

    const cards = videos
      .filter((v) => v.category === col)
      .map((v, i) => {
        const n = existing + i + 1;
        const list = v.list ? ` data-list="${esc(v.list)}"` : "";
        return (
          `<div class="slot"><article class="card">` +
          `<button aria-label="${esc(`הפעל סרטון ${n}, ${heading[1]}`)}" class="thumb" data-id="${v.id}"${list} type="button">` +
          `<img alt="" decoding="async" loading="lazy" src="https://i.ytimg.com/vi/${v.id}/hqdefault.jpg"/>` +
          `<span aria-hidden="true" class="play"></span></button>` +
          `<p class="ttl">${esc(v.title)}</p><span class="num">${n}</span></article></div>`
        );
      });

    html = replaceBetween(html, start, end, cards.length ? cards.join("\n") + "\n" : "", INDEX_FILE);
  }

  // The header shows how many videos the page has, so keep it in step with the cards.
  const total = (html.match(/class="thumb"/g) || []).length;
  const countLine = /<p>\d+ סרטונים<\/p>/;
  if (!countLine.test(html)) throw new Error('index.html is missing the "<p>N סרטונים</p>" header line');
  html = html.replace(countLine, `<p>${total} סרטונים</p>`);

  await writeFile(INDEX_FILE, html, "utf8");
}

const articles = await loadArticles();
const videos = await loadVideos();
await writeArticles(articles);
await updateArticleLists(articles);
await updateIndex(videos);
console.log(`Built ${articles.length} article(s) and ${videos.length} video(s).`);
